# -- Python arithmetic semantics (floored div/mod, pow, zero division) -----

@needs_cc
def test_negative_mod_and_floordiv():
    assert run("""
def main() -> None:
    print(-7 % 3)
    print(7 % -3)
    print(-7 // 3)
    print(7 // -3)
""") == "2\n-2\n-3\n-3\n"


@needs_cc
def test_float_mod_sign_follows_divisor():
    assert run("""
def main() -> None:
    print(7.5 % -2.0)
""") == "-0.5\n"


@needs_cc
def test_int_pow_stays_integral():
    assert run("""
def main() -> None:
    print(2 ** 62)
""") == "4611686018427387904\n"


@needs_cc
def test_zero_division_aborts():
    src = """
def main() -> None:
    print(1 // 0)
"""
    c = compile_to_c(src)
    with tempfile.TemporaryDirectory() as d:
        cf = os.path.join(d, "out.c")
        binf = os.path.join(d, "out")
        with open(cf, "w") as f:
            f.write(c)
        subprocess.run([CC, "-O2", "-o", binf, cf, "-lm"], check=True)
        r = subprocess.run([binf], capture_output=True, text=True)
        assert r.returncode == 1
        assert "ZeroDivisionError" in r.stderr


@needs_cc
def test_str_concat():
    assert run("""
def main() -> None:
    print("ab" + "cd")
""") == "abcd\n"


@needs_cc
def test_range_negative_and_variable_step():
    assert run("""
def main() -> None:
    s: int = 0
    for i in range(10, 0, -2):
        s += i
    print(s)
    n: int = 3
    for j in range(0, 10, n):
        s += j
    print(s)
""") == "30\n48\n"


@needs_cc
def test_augassign_python_semantics():
    assert run("""
def main() -> None:
    x: int = 7
    x //= 2
    x %= -3
    print(x)
""") == "0\n"


@needs_cc
def test_print_multiple_args():
    assert run("""
def main() -> None:
    print(1, "two", 3.5, True)
""") == "1 two 3.5 True\n"


def test_int_truediv_augassign_rejected():
    with pytest.raises(UnsupportedError):
        compile_to_c("""
def main() -> None:
    x: int = 7
    x /= 2
""")
